INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass alle Mängel in IT-Systemen immer Softwarefehler sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardwarefehler möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Mängelarten in einem IT-System analysiere?', 3, '[{"text": "Fehlerursache", "correct": true, "because": "Bestimmt Lösung"}, {"text": "Schnellste Meldung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mängelarten treten in IT-Systemen auf?', 5, '[{"text": "Hardwaredefekte", "correct": true, "because": "Physische Schäden"}, {"text": "Softwarefehler", "correct": true, "because": "Programmierfehler"}, {"text": "Büroausstattung", "correct": false, "because": "Kein IT-Mangel"}, {"text": "Marketingfehler", "correct": false, "because": "Nicht systemrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konfigurationsfehler sind eine Mängelart. b) Alle Mängel sind sofort sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft schwer erkennbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Mängelarten in einem IT-System untersuche?', 4, '[{"text": "Fehlerprotokolle", "correct": false, "because": "Zeigen Ursachen"}, {"text": "Systemlogs", "correct": false, "because": "Enthalten Hinweise"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mängelarten nur Hardware betreffen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software und Konfiguration"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Mängelarten in einem IT-System identifiziere?', 3, '[{"text": "Systemzuverlässigkeit", "correct": true, "because": "Verbessert Betrieb"}, {"text": "Schnellste Reparatur", "correct": false, "because": "Analyse wichtiger"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorien von Mängelarten gibt es in IT-Systemen?', 5, '[{"text": "Netzwerkfehler", "correct": true, "because": "Stören Kommunikation"}, {"text": "Benutzerfehler", "correct": true, "because": "Falsche Bedienung"}, {"text": "Büroausstattung", "correct": false, "because": "Kein IT-Mangel"}, {"text": "Marketingstrategie", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Hardwarefehler sind eine Mängelart. b) Mängel sind immer absichtlich verursacht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unabsichtlich möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Mängelarten in einem IT-System zu beheben?', 4, '[{"text": "Fehlerdiagnose", "correct": false, "because": "Identifiziert Ursache"}, {"text": "Protokollanalyse", "correct": false, "because": "Zeigt Probleme"}, {"text": "Bürofarben", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Mängelarten immer sofort erkennbar?', 2, '[{"text": "Nein", "correct": true, "because": "Oft versteckt"}, {"text": "Ja", "correct": false, "because": "Analyse nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Identifikation von Mängelarten?', 4, '[{"text": "Systemstabilität", "correct": true, "because": "Vermeidet Ausfälle"}, {"text": "Fehlerprävention", "correct": true, "because": "Verhindert Wiederholung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Mängelarten nur bei Hardware auftreten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software und Nutzer"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Mängelarten in einem IT-System zu erkennen?', 3, '[{"text": "Monitoring-Tools", "correct": true, "because": "Zeigen Fehler"}, {"text": "Schnellste Software", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerkfehler sind eine Mängelart. b) Alle Mängel sind hardwarebedingt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Analyse von Mängelarten?', 5, '[{"text": "Fehlerhäufigkeit", "correct": true, "because": "Zeigt Priorität"}, {"text": "Fehlerursache", "correct": true, "because": "Bestimmt Lösung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Mängelarten in einem IT-System untersuche?', 3, '[{"text": "Logdateien", "correct": false, "because": "Zeigen Fehler"}, {"text": "Systemkonfiguration", "correct": false, "because": "Beeinflusst Mängel"}, {"text": "Büroausstattung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Mängelarten immer absichtlich verursacht?', 3, '[{"text": "Nein", "correct": true, "because": "Oft unbeabsichtigt"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mängelarten nur technische Fehler umfassen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Benutzerfehler"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
